class Solution:
    def countSubstrings(self, s: str) -> int:
        count = 0
        def expand(l, r):
            nonlocal count
            while l >= 0 and r < len(s) and s[l] == s[r]:
                count += 1
                l -= 1
                r += 1
        for i in range(len(s)):
            expand(i, i)
            expand(i, i+1)
        return count

reference_solution.javascript:
function countSubstrings(s) {
    let count = 0;
    function expand(l, r) {
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            count++;
            l--;
            r++;
        }
    }
    for (let i = 0; i < s.length; i++) {
        expand(i, i);
        expand(i, i+1);
    }
    return count;
}
